/* The page, built from the run in data.js.
 *
 * Three rules this file follows:
 *
 *   1. No number is written here. Every figure comes from `M`, generated by
 *      tools/render_results.py from results/zero.json — and every ratio or verdict the prose quotes
 *      is computed there too, in `page_numbers()`, so this file only reads and formats.
 *   2. A mechanism figure is not a results chart. The page draws which of a weight's bytes each
 *      stage keeps whole, and a ring passing chunks step by step, before it shows a single count.
 *   3. A failure goes in the opening tiles, and a prediction is drawn as a prediction: everything
 *      at thirty billion weights is arithmetic, so it is dashed or hatched, never solid.
 *
 * Sections carry `data-role`, so the spine is checkable without pinning any wording.
 *
 * Colour has one job here: **a byte is coloured by the stage that first splits it.** Optimiser
 * state is ZeRO-1's colour, gradients ZeRO-2's, weights ZeRO-3's, and data parallelism — which
 * splits nothing — has the accent. The same four hues are the four stages in every line chart, so a
 * reader who learns the mapping once can read every figure with it.
 */

const NS = 'http://www.w3.org/2000/svg';
const main = () => document.getElementById('main');

function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text !== undefined) n.textContent = text;
  return n;
}

function svg(tag, attrs = {}) {
  const n = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, String(v));
  /* **A figure is never drawn smaller than it was designed, because its labels shrink with it.**
   * A `viewBox` scales text along with the drawing, so a label authored at a compliant 11px paints
   * at `11 × rendered ÷ viewBox` — 5px on a phone, where the figure is a quarter of its design
   * width. Nothing in the source says so: every declared size on this page is inside
   * `docs/DESIGN.md`'s 9.5–11px band, and the whole reduction happens in the transform.
   *
   * A diagram cannot reflow the way a paragraph can, so the fix is to stop it shrinking: the floor
   * is the viewBox's own width, and the `figure` around it already scrolls. Set here rather than in
   * a stylesheet because the value is a property of each drawing, and a stylesheet would have to
   * repeat every viewBox — a second copy of a number, which is the copy that drifts. */
  if (tag === 'svg' && attrs.viewBox) {
    const designed = Number(String(attrs.viewBox).trim().split(/\s+/)[2]);
    if (Number.isFinite(designed) && designed > 0) n.style.minWidth = `${designed}px`;
  }
  return n;
}

function svgText(x, y, cls, text) {
  const t = svg('text', { x, y, class: cls });
  t.textContent = text;
  return t;
}

let sectionCount = 0;
let figureCount = 0;

/** A section whose eyebrow names its epistemic role, so a reader knows how to weigh it. */
function section(id, role, eyebrow, title, paras, rail) {
  const s = el('section');
  s.id = id;
  s.dataset.role = role;
  sectionCount += 1;
  s.dataset.n = String(sectionCount);
  s.dataset.title = (rail && rail.short) || title;
  if (rail && rail.sub) s.dataset.sub = rail.sub;
  s.append(el('p', 'role', eyebrow), el('h2', null, title));
  for (const p of [].concat(paras || [])) {
    const n = el('p', 'say');
    n.innerHTML = p;
    s.append(n);
  }
  main().append(s);
  return s;
}

/** A figure whose caption says what to conclude — never a bare label.
 *
 * **The number is counted, not passed** (from exercise 09, which shipped two Figure 1s when it was
 * an argument). A figure's number is a count of the figures before it.
 */
function figure(node, caption) {
  figureCount += 1;
  const f = el('figure');
  f.append(node);
  const c = el('figcaption');
  c.innerHTML = `<b>Figure ${figureCount}.</b> ${caption}`;
  f.append(c);
  return f;
}

function table(head, rows, cls) {
  const wrap = el('div', 'tablewrap');
  const t = el('table', cls || 'grid');
  const thead = el('thead');
  const hr = el('tr');
  for (const h of head) {
    const th = el('th');
    th.innerHTML = h;
    hr.append(th);
  }
  thead.append(hr);
  t.append(thead);
  const tb = el('tbody');
  for (const row of rows) {
    const tr = el('tr');
    if (row.__mark) tr.className = row.__mark;
    row.cells.forEach((cell, i) => {
      const td = el('td');
      td.innerHTML = cell === null || cell === undefined ? '—' : cell;
      /* The column head, carried on the cell, so a stacked row on a phone can still say which
       * column each line belongs to. Only when there IS one: an empty `data-head` still matches
       * `td[data-head]` and paints an empty labelled line above the value. */
      const label = head[i] === undefined ? '' : String(head[i]).replace(/<[^>]*>/g, '').trim();
      if (label) td.dataset.head = label;
      tr.append(td);
    });
    tb.append(tr);
  }
  t.append(tb);
  wrap.append(t);
  return wrap;
}

const int = (n) => Math.round(n).toLocaleString('en-US');
/* Counts are SPELLED from the data, never typed. A heading or a rail label that states a number
 * is stating a count of its own contents, so typing it is how a page comes to be headed "Two
 * commands" over three of them. Ported from exercise 08, which introduced it for the same reason. */
const SPELLED = [
  'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
  'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen',
  'nineteen', 'twenty',
];
const spell = (n) => SPELLED[n] || String(n);
const Spell = (n) => {
  const w = spell(n);
  return w[0].toUpperCase() + w.slice(1);
};

const signed = (n, d = 4) => (n >= 0 ? '+' : '−') + Math.abs(n).toFixed(d);
const pct = (n, d = 1) => `${(n * 100).toFixed(d)}%`;

/* ------------------------------------------------------------------ this page's own formatting */

/** Bytes per weight: exact quarters and sixteenths print in full, nothing is padded with zeros. */
const bpw = (v) => String(Number(v.toPrecision(6)));
/** A tiny difference, in the notation `RESULTS.md` uses for it. */
const sci = (v) => (v === 0 ? '0' : v.toExponential(2).replace('e-', ' × 10<sup>−').replace(/$/, '</sup>'));
const gib = (v) => v.toFixed(1);
const usec = (seconds, d = 2) => (seconds * 1e6).toFixed(d);

const STAGES = ['0', '1', '2', '3'];
const CATS = ['params', 'grads', 'master', 'adam_m', 'adam_v'];
const CAT_LABEL = {
  params: 'weights',
  grads: 'gradients',
  master: 'fp32 master copy',
  adam_m: 'Adam m',
  adam_v: 'Adam v',
};
const CAT_SHORT = { params: 'W', grads: 'G', master: 'M', adam_m: 'm', adam_v: 'v' };
/** Column heads short enough to sit over a few cells of a drawing. */
const CAT_HEAD = { params: 'weight', grads: 'gradient', master: 'master', adam_m: 'Adam m', adam_v: 'Adam v' };

/** The stage's name as the run records it, shortened for a label that sits on a drawing. */
const tag = (key) => (key === '0' ? 'DP' : `ZeRO-${key}`);

/** The colour class of a byte: the first stage that shards its category, read from the formulas. */
const catSeries = (M, cat) => {
  const F = M.page.formula[M.main_mode];
  return `s${STAGES.find((k) => F[k].sharded[cat])}`;
};

/** A shared morph: ~550ms ease, or the end state at once where motion is unwanted. */
const reduceMotion = () =>
  Boolean(window.matchMedia) && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2);
function morph(apply, duration = 550) {
  if (reduceMotion()) {
    apply(1);
    return;
  }
  const start = performance.now();
  const tick = (now) => {
    const t = Math.min(1, (now - start) / duration);
    apply(ease(t));
    if (t < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

/** A drawing's own horizontal scroller, so on a phone the drawing scrolls and the controls and the
 * readout around it stay put. A grid or flex child's `min-width` defaults to its content, so the
 * wrapper needs `min-width: 0` as well as `overflow-x: auto` (docs/DESIGN.md). */
function scroller(node) {
  const box = el('div', 'figscroll');
  box.append(node);
  return box;
}

/** Every interactive figure registers its end state here, so print and reduced motion paint it. */
const PLAYABLE = [];

/** A row of `.tabs` buttons with `aria-pressed`, arrow keys moving within the group. */
function tabs(label, options, onPick) {
  const holder = el('div', 'tabs');
  holder.setAttribute('role', 'group');
  holder.setAttribute('aria-label', label);
  const buttons = options.map(([value, text]) => {
    const b = el('button', null, text);
    b.type = 'button';
    b.dataset.value = value;
    b.setAttribute('aria-pressed', 'false');
    b.addEventListener('click', () => onPick(value));
    holder.append(b);
    return b;
  });
  holder.addEventListener('keydown', (e) => {
    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
    const i = buttons.indexOf(document.activeElement);
    if (i < 0) return;
    const next = buttons[(i + (e.key === 'ArrowRight' ? 1 : buttons.length - 1)) % buttons.length];
    next.focus();
    next.click();
    e.preventDefault();
  });
  holder.mark = (value) => {
    for (const b of buttons) b.setAttribute('aria-pressed', String(b.dataset.value === value));
  };
  return holder;
}

/* ============================================================== 1 · thesis */

function chapterThesis(M) {
  const main_ = M.modes[M.main_mode];
  const P = M.page;
  const world = M.topology.world_size;
  const s = section(
    'thesis',
    'thesis',
    'What was counted',
    'The bytes do not shrink. They move.',
    [
      `${int(world)} simulated devices train one small model ${spell(STAGES.length)} ways: plain data
       parallelism, and ZeRO stages ${STAGES.slice(1, -1).join(', ')} and ${STAGES[STAGES.length - 1]}.
       On every device a ledger adds up the bytes of every
       buffer the stage keeps, and a counter adds up every byte the device sends. <b>Both equal a
       formula worked out by hand, in every category, on every device</b> — and all
       ${spell(STAGES.length)} ways end on the same weights, to the last bit.`,
    ],
    { short: 'The claim', sub: 'what ZeRO changes, and what it cannot' }
  );

  const ladder = M.ladder;
  const tiles = el('div', 'tiles');
  for (const [v, k, mark] of [
    [
      `${bpw(P.per_weight[M.main_mode]['0'].total)} → ${bpw(P.per_weight[M.main_mode]['3'].total)}`,
      `bytes per weight on each device at N&nbsp;=&nbsp;${int(world)}, data parallelism against
       ZeRO-3 — measured by the ledger, and equal to the hand formula in every category`,
      'good',
    ],
    [
      `${P.zero3_sent_over_dp}×`,
      `the bytes ZeRO-3 sends each step, against data parallelism. ZeRO-1 and ZeRO-2 send
       <b>exactly</b> what data parallelism sends: ${int(main_['1'].communication.per_step_sent.total)}
       bytes, to the byte`,
      'watch',
    ],
    [
      `${P.max_abs_vs_dp}`,
      `the largest difference from data parallelism's trained weights, over all
       ${spell(P.zero_runs_compared)} ZeRO runs in both precisions. Bit-identical — in this
       simulator, for a reason the page explains`,
      'good',
    ],
    [
      `${gib(P.slider.floor_gib['1'])} GiB`,
      `ZeRO-1's floor for a ${ladder.params / 1e9}-billion-weight model: what stays on every device
       however many are added. The card holds ${gib(ladder.card_gib)} GiB, so <b>ZeRO-1 never fits,
       at any N</b>. Predicted by the formulas, not run`,
      'bad',
    ],
  ]) {
    const tile = el('div', `tile ${mark}`);
    const value = el('div', 'tile-v');
    value.innerHTML = v;
    const key = el('div', 'tile-k');
    key.innerHTML = k;
    tile.append(value, key);
    tiles.append(tile);
  }
  s.append(tiles);

  const note = el('p', 'say small');
  note.innerHTML = `The red tile is the one most worth reading. Adding devices is the usual answer to
    "it does not fit", and for data parallelism and ZeRO-1 it is no answer at all: part of what they
    keep is copied whole onto every device, and no number of devices makes a whole copy smaller.`;
  s.append(note);
}

/* ============================================================== 2 · glossary */

function chapterGlossary(M) {
  const mm = M.modes[M.main_mode];
  const fp = M.modes.fp32;
  const P = M.page;
  const pw = P.per_weight[M.main_mode]['0'];
  const topo = M.topology;
  const embed = M.model.units[0];
  const padRow = M.scaling.rows.find((r) => r.measured !== r.measured_real && r.stage === 3);
  const entries = [
    [
      'data parallelism',
      `Every device keeps a complete copy of the model and trains it on a different slice of the
       batch, then the devices average their gradients so the copies stay identical. Here that is
       ${int(mm['0'].memory.measured.total)} bytes on each of ${int(topo.world_size)} devices.`,
    ],
    [
      'a weight’s training state',
      `What one weight costs while it is being trained: the weight itself (${bpw(pw.params)} bytes in
       bf16), its gradient (${bpw(pw.grads)}), a full-precision master copy (${bpw(pw.master)}), and
       Adam’s two running averages (${bpw(pw.adam_m)} each) — ${spell(pw.total)} bytes in all.`,
    ],
    [
      'bf16 and fp32',
      `Two ways to store a number: bf16 in ${bpw(pw.params)} bytes, fp32 in
       ${bpw(P.per_weight.fp32['0'].params)}. <b>bf16-mixed</b> computes in bf16
       and keeps the fp32 master copy; plain <b>fp32</b> needs no master copy, because the weight
       already is one. Both come to ${bpw(P.per_weight.fp32['0'].total)} bytes a weight here.`,
    ],
    [
      'a shard',
      `One device’s slice of a buffer. The model is cut into units (embeddings, each block, the
       head), each unit’s buffer into ${int(topo.world_size)} equal slices, and device <i>r</i> keeps
       slice <i>r</i> of every one — ${int(embed.shard)} of the embedding table’s
       ${int(embed.numel)} weights.`,
    ],
    [
      'ZeRO',
      `The Zero Redundancy Optimizer: stop keeping identical copies. <b>Stage 1</b> shards the
       optimiser state, <b>stage 2</b> the gradients too, <b>stage 3</b> the weights too. At
       N&nbsp;=&nbsp;${int(topo.world_size)}, ZeRO-3 keeps ${int(mm['3'].memory.measured.total)} bytes
       per device.`,
    ],
    [
      'the floor',
      `What a stage keeps whole however many devices are added — the bytes it never shards.
       ${bpw(P.formula[M.main_mode]['1'].floor)} bytes per weight for ZeRO-1,
       ${bpw(P.formula[M.main_mode]['2'].floor)} for ZeRO-2, ${bpw(P.formula[M.main_mode]['3'].floor)}
       for ZeRO-3.`,
    ],
    [
      'a ring',
      `Devices connected in a loop, each sending only to the next. Here ${int(topo.world_size)}
       devices sit on ${int(topo.nodes)} machines of ${int(topo.devices_per_node)}, so
       ${int(topo.ring_links.intra)} links of the ring stay inside a machine and
       ${int(topo.ring_links.inter)} cross between machines.`,
    ],
    [
      'P',
      `The size of one full copy of the weights, in the dtype gradients travel in:
       ${int(mm['0'].communication.payload_bytes)} bytes here. Every communication cost on the page
       is a multiple of it.`,
    ],
    [
      'reduce-scatter and all-gather',
      `The two ring operations. A <b>reduce-scatter</b> sums a buffer across devices and leaves each
       with only its own slice of the sum; an <b>all-gather</b> hands every device every slice. Each
       sends P·(N−1)/N per device: ${int(mm['0'].communication.per_step_sent.reduce_scatter)} bytes.`,
    ],
    [
      'all-reduce',
      `Every device ends with the whole sum. In a ring it <i>is</i> a reduce-scatter followed by an
       all-gather — data parallelism’s ${int(mm['0'].communication.per_step_sent.total)} bytes a step
       are those two phases added.`,
    ],
    [
      'padding',
      `Zeros added so a buffer cuts into equal slices. None is needed at the sizes this run uses
       except N&nbsp;=&nbsp;${int(padRow.world_size)}, where ZeRO-3 costs ${bpw(padRow.measured_real)}
       bytes per real weight instead of ${bpw(padRow.measured)}.`,
    ],
    [
      'a transient buffer',
      `Memory a stage needs only for a moment: ZeRO-3 gathers one unit’s full weights to use them,
       then frees them. The largest unit is ${int(mm['3'].memory.largest_unit_bytes.params)} bytes of
       bf16 weights (${int(fp['3'].memory.largest_unit_bytes.params)} in fp32).`,
    ],
  ];
  const s = section(
    'glossary',
    'glossary',
    'Before anything else',
    `${Spell(entries.length)} words this page leans on, each with a figure from the run`,
    [
      `Read this once and nothing below is jargon. Every entry carries a real figure from the run on
       this page rather than a textbook gloss.`,
    ],
    { short: 'The words', sub: `${spell(entries.length)} terms, with our own figures` }
  );

  const dl = el('dl', 'gloss');
  for (const [term, def] of entries) {
    dl.append(el('dt', null, term));
    const dd = el('dd');
    dd.innerHTML = def;
    dl.append(dd);
  }
  s.append(dl);
}

/* ============================================================== 3 · the problem */

function chapterProblem(M) {
  const mm = M.modes[M.main_mode];
  const pw = M.page.per_weight[M.main_mode]['0'];
  const world = M.topology.world_size;
  const optimiserBytes = pw.master + pw.adam_m + pw.adam_v;
  const s = section(
    'problem',
    'problem',
    'The problem',
    'Data parallelism stores the same state on every device',
    [
      `Data parallelism works, and it is wasteful in one exact way: <b>every device keeps the same
       training state</b>. ${int(world)} devices hold ${int(world)} identical copies — like a team of
       accountants who each keep a full copy of one enormous ledger, when each could keep a share of
       the pages and borrow a page from a colleague at the moment it is needed.`,
      `The state is bigger than the model. A finished model needs its weights; a model in training
       needs ${spell(pw.total)} bytes for every weight, and ${spell(optimiserBytes)} of them exist only
       for the optimiser.`,
    ],
    { short: 'The waste', sub: 'every device keeps the same bytes' }
  );

  const rows = CATS.map((c) => ({
    cells: [
      CAT_LABEL[c],
      c === 'params' || c === 'grads' ? 'bf16' : 'fp32',
      bpw(pw[c]),
      int(mm['0'].memory.measured[c]),
      {
        params: 'what the forward and backward pass compute with',
        grads: 'produced by the backward pass, averaged across devices',
        master: 'bf16 is too coarse to add many tiny updates into, so the update lands here',
        adam_m: 'a running average of the gradient',
        adam_v: 'a running average of the squared gradient',
      }[c],
    ],
  }));
  rows.push({
    cells: [
      '<b>total</b>',
      '',
      `<b>${bpw(pw.total)}</b>`,
      `<b>${int(mm['0'].memory.measured.total)}</b>`,
      'on <b>every</b> device, under data parallelism',
    ],
  });
  s.append(
    table(
      ['what', 'stored as', 'bytes per weight', 'bytes on one device, measured', 'why it exists'],
      rows,
      'grid prose'
    )
  );

  const tail = el('p', 'say');
  tail.innerHTML = `Activations — the values each example produces on its way through the network —
    come on top, scale with the batch, and are a separate bill that ZeRO does not split. Everything
    on this page is about the table above.`;
  s.append(tail);
}

/* ============================================================== 4 · mechanism */

function stagesFigure(M) {
  const mode = M.main_mode;
  const F = M.page.formula[mode];
  const pw = M.page.per_weight[mode];
  const world = M.topology.world_size;
  const cell = 26;
  const gap = 3;
  const groupGap = 12;
  const x0 = 104;
  const rowH = 56;
  const top = 44;
  const widths = CATS.map((c) => Math.round(pw['0'][c]));
  const gridW = widths.reduce((a, n) => a + n * (cell + gap), 0) + groupGap * (CATS.length - 1);
  const w = x0 + gridW + 150;
  const h = top + rowH * STAGES.length + 10;

  const node = svg('svg', {
    viewBox: `0 0 ${w} ${h}`,
    class: 'figsvg stagefig',
    role: 'img',
    'aria-label':
      'For each stage, the bytes of one weight drawn as cells: solid cells are kept whole on every ' +
      'device, outlined cells are split across the devices.',
  });

  // Category heads, once, over the columns they label.
  let x = x0;
  CATS.forEach((c, i) => {
    const span = widths[i] * (cell + gap) - gap;
    node.append(svgText(x + span / 2, 18, 'lab mid', CAT_HEAD[c]));
    node.append(svgText(x + span / 2, 32, 'lab mid faint', `${bpw(pw['0'][c])} B`));
    x += span + gap + groupGap;
  });
  node.append(svgText(w - 140, 32, 'lab', `per weight · N = ${int(world)}`));

  STAGES.forEach((k, r) => {
    const y = top + r * rowH;
    node.append(svgText(0, y + cell / 2 + 5, `lab strong`, tag(k)));
    let cx = x0;
    CATS.forEach((c, i) => {
      const sharded = F[k].sharded[c];
      for (let b = 0; b < widths[i]; b += 1) {
        node.append(
          svg('rect', {
            x: cx,
            y,
            width: cell,
            height: cell,
            rx: 4,
            class: `byte ${catSeries(M, c)} ${sharded ? 'split' : 'whole'}`,
          })
        );
        cx += cell + gap;
      }
      cx += groupGap;
    });
    const formula =
      F[k].floor === pw['0'].total
        ? `${bpw(F[k].floor)}`
        : F[k].floor === 0
          ? `${bpw(pw['0'].total)}/N`
          : `${bpw(F[k].floor)} + ${bpw(pw['0'].total - F[k].floor)}/N`;
    node.append(svgText(w - 140, y + 12, 'lab', formula));
    node.append(svgText(w - 140, y + 28, 'val', `= ${bpw(pw[k].total)}`));
  });

  return node;
}

/* -------------------------------------------------------- the ring, stepped (Simulator)
 *
 * Family: Simulator (EXPLAINER_PROMPT §10) — "X causes Y": every step sends one chunk from each
 * device to the next, and the reader watches sums complete and the byte counter climb. Topology:
 * single canvas, one control. The shape is EXPLAINER_PATTERN §4: guard → pure stateFor → show.
 *
 * **The order of sends is the simulator's, not a textbook's.** `collectives.py` starts rank r on
 * chunk r − 1 and leaves rank r holding the complete chunk r; `stateFor` runs exactly that loop on
 * counts instead of tensors, so the drawing and the code that was measured cannot disagree.
 */
function ringExplainer(M) {
  const R = M.page.ring;
  const n = R.world_size;
  const last = 2 * (n - 1);
  const mod = (a) => ((a % n) + n) % n;

  /* stateFor(t) — PURE. Steps taken → every number the renderer needs. */
  const stateFor = (t) => {
    const parts = Array.from({ length: n }, () => Array(n).fill(1)); // contributions per cell
    const done = Array.from({ length: n }, () => Array(n).fill(false));
    let sends = [];
    // reduce-scatter: the loop in collectives.reduce_scatter, on counts.
    let out = Array.from({ length: n }, (_, r) => ({ chunk: mod(r - 1), k: 1 }));
    const rsSteps = Math.min(t, n - 1);
    for (let step = 0; step < rsSteps; step += 1) {
      sends = out.map((o, src) => ({ src, chunk: o.chunk }));
      const incoming = out.map((_, dst) => out[mod(dst - 1)]);
      out = incoming.map((inc, rank) => {
        const chunk = mod(rank - step - 2);
        parts[rank][chunk] = inc.k + 1;
        return { chunk, k: inc.k + 1 };
      });
    }
    for (let r = 0; r < n; r += 1) for (let c = 0; c < n; c += 1) done[r][c] = parts[r][c] === n;
    // all-gather: the loop in collectives.all_gather.
    const agSteps = Math.max(0, t - (n - 1));
    let ag = Array.from({ length: n }, (_, r) => r);
    for (let step = 0; step < agSteps; step += 1) {
      sends = ag.map((chunk, src) => ({ src, chunk }));
      const incoming = ag.map((_, dst) => ag[mod(dst - 1)]);
      ag = incoming.map((_, rank) => {
        const chunk = mod(rank - step - 1);
        done[rank][chunk] = true;
        return chunk;
      });
    }
    if (t === 0) sends = [];
    return {
      t,
      phase: t === 0 ? 'before' : t <= n - 1 ? 'reduce-scatter' : 'all-gather',
      parts,
      done,
      sends,
      sentBytes: t * R.chunk_bytes,
      owned: t >= n - 1,
    };
  };

  /* guard() — the precondition. A step outside the two phases has no honest picture. */
  const guard = (t) => (t < 0 || t > last ? { note: 'There is no such step in this ring.' } : null);

  const cw = 62;
  const ch = 40;
  const x0 = 96;
  const y0 = 46;
  const gapY = 14;
  const W = x0 + n * (cw + 8) + 176;
  const H = y0 + n * (ch + gapY) + 10;
  const wrap = el('div', 'ring');
  const chart = svg('svg', {
    viewBox: `0 0 ${W} ${H}`,
    class: 'figsvg ringfig',
    role: 'img',
    'aria-label':
      `A ring of ${n} devices, each holding ${n} chunks of the gradient buffer; arrows show which ` +
      'chunk each device sends to the next at the current step.',
  });
  for (let c = 0; c < n; c += 1) {
    chart.append(svgText(x0 + c * (cw + 8) + cw / 2, 30, 'lab mid', `chunk ${c}`));
  }
  const cells = [];
  const texts = [];
  for (let r = 0; r < n; r += 1) {
    const y = y0 + r * (ch + gapY);
    chart.append(svgText(0, y + ch / 2 + 5, 'lab strong', `device ${r}`));
    cells.push([]);
    texts.push([]);
    for (let c = 0; c < n; c += 1) {
      const rect = svg('rect', { x: x0 + c * (cw + 8), y, width: cw, height: ch, rx: 6, class: 'chunk' });
      const txt = svgText(x0 + c * (cw + 8) + cw / 2, y + ch / 2 + 5, 'chunk-t mid', '');
      chart.append(rect, txt);
      cells[r].push(rect);
      texts[r].push(txt);
    }
  }
  const xr = x0 + n * (cw + 8) + 16;
  const arrows = svg('g', { class: 'ring-arrows' });
  chart.append(arrows);

  const controls = el('div', 'ring-ctl');
  const label = el('label', null, 'Ring step');
  const range = el('input');
  range.type = 'range';
  range.min = '0';
  range.max = String(last);
  range.step = '1';
  range.value = '0';
  range.id = 'ring-step';
  label.htmlFor = 'ring-step';
  const output = el('output', 'ring-out');
  output.htmlFor = 'ring-step';
  controls.append(label, range, output);
  const read = el('div', 'ring-read');
  read.setAttribute('aria-live', 'polite');

  /* show(t) — RENDER ONLY. Checks guard() first, computes nothing itself. */
  const show = (t) => {
    range.value = String(t);
    const refused = guard(t);
    if (refused) {
      read.textContent = refused.note;
      return;
    }
    const st = stateFor(t);
    output.textContent = `${st.t} of ${last}`;
    for (let r = 0; r < n; r += 1) {
      for (let c = 0; c < n; c += 1) {
        const k = st.parts[r][c];
        const full = st.done[r][c];
        const stale = st.phase === 'all-gather' && !full;
        cells[r][c].setAttribute('class', `chunk${full ? ' full' : ''}${stale ? ' stale' : ''}`);
        cells[r][c].style.setProperty('--fill', String(full ? 1 : k / n));
        texts[r][c].textContent = full ? 'Σ' : stale ? '' : `${k}/${n}`;
        texts[r][c].setAttribute('class', `chunk-t mid${full ? ' on' : ''}`);
      }
    }
    arrows.replaceChildren();
    for (const send of st.sends) {
      const ya = y0 + send.src * (ch + gapY) + ch / 2;
      const dst = mod(send.src + 1);
      const yb = y0 + dst * (ch + gapY) + ch / 2;
      if (dst > send.src) {
        arrows.append(
          svg('path', { d: `M ${xr} ${ya + 6} L ${xr} ${yb - 8}`, class: 'arrow' }),
          svg('path', { d: `M ${xr - 5} ${yb - 14} L ${xr} ${yb - 6} L ${xr + 5} ${yb - 14}`, class: 'arrow' }),
          svgText(xr + 10, (ya + yb) / 2 + 4, 'lab', `chunk ${send.chunk}`)
        );
      } else {
        /* The wrap-around goes OUTSIDE the down arrows, and its label sits outside it again: the
         * first draft centred both labels on the same row gap and printed one over the other. */
        const xw = xr + 92;
        arrows.append(
          svg('path', {
            d: `M ${xr + 4} ${ya} L ${xw} ${ya} L ${xw} ${yb} L ${xr + 8} ${yb}`,
            class: 'arrow wrapback',
          }),
          svg('path', { d: `M ${xr + 14} ${yb - 5} L ${xr + 6} ${yb} L ${xr + 14} ${yb + 5}`, class: 'arrow' }),
          svgText(xw + 6, (ya + yb) / 2 - 4, 'lab', `chunk ${send.chunk}`),
          svgText(xw + 6, (ya + yb) / 2 + 12, 'lab faint', `to ${dst}`)
        );
      }
    }
    const phaseLine = {
      before: `<b>Before the first step.</b> Every device holds its own gradient for all ${n} chunks —
        each cell holds one of the ${n} contributions its chunk's sum will need.`,
      'reduce-scatter': `<b>Reduce-scatter, step ${st.t}.</b> Each device passes one running sum to the
        next, which adds its own copy of that chunk.${st.owned ? ` <b>Every device now owns one complete
        chunk</b> — device <i>r</i> holds the whole sum of chunk <i>r</i>. ZeRO-2 stops here and keeps it.` : ''}`,
      'all-gather': `<b>All-gather, step ${st.t - (n - 1)}.</b> Each device forwards the complete chunk
        it most recently received.${st.t === last ? ` <b>Every device now has every sum</b> —
        together, the two phases are an all-reduce.` : ''}`,
    }[st.phase];
    read.innerHTML = `${phaseLine} <span class="ring-bytes">Each device has sent
      <b>${int(st.sentBytes)}</b> bytes (${st.t} × ${int(R.chunk_bytes)}).</span>`;
  };

  range.addEventListener('input', () => show(Number(range.value)));
  wrap.playAll = () => show(last);
  PLAYABLE.push(wrap);
  wrap.append(controls, scroller(chart), read);
  show(0);
  return wrap;
}

function chapterMechanism(M) {
  const mm = M.modes[M.main_mode];
  const R = M.page.ring;
  const world = M.topology.world_size;
  const embed = M.model.units[0];
  const s = section(
    'mechanism',
    'mechanism',
    'The stages, by hand',
    'Each stage stops copying one more kind of state',
    [
      `Every ZeRO stage keeps the same ${spell(M.page.per_weight[M.main_mode]['0'].total)} bytes per
       weight as data parallelism. What changes is which of them are <b>kept whole on every device</b>
       and which are <b>split ${int(world)} ways</b>, each device keeping one slice.`,
    ],
    { short: 'The stages', sub: 'which bytes each stage splits' }
  );

  s.append(
    figure(
      stagesFigure(M),
      `<b>Read each row left to right: a solid cell is a byte every device keeps whole, an outlined
       cell is a byte split across the devices.</b> Data parallelism keeps all of them; each stage
       outlines one more group, and the colour of a group is the stage that first splits it. The
       column on the right is the same thing as arithmetic. <b>What would refute the picture:</b> a
       ledger reading other than the right-hand value — which the
       <a href="#results">results</a> check category by category.`
    )
  );

  const floorNote = el('p', 'say');
  floorNote.innerHTML = `<b>The constant term is the floor.</b> Whatever a stage keeps whole stays on
    every device however many are added, so ZeRO-1 can never go below
    ${bpw(M.page.formula[M.main_mode]['1'].floor)} bytes per weight and data parallelism never moves
    at all. Only ZeRO-3 has no floor. That is why the stages differ in kind and not only in degree.`;
  s.append(floorNote);

  const h3 = el('h3', null, 'What moves between the devices');
  s.append(h3);
  const ringIntro = el('p', 'say');
  ringIntro.innerHTML = `Splitting state means devices must trade pieces of it, and they trade around
    a <b>ring</b>: device <i>r</i> only ever sends to device <i>r</i>&nbsp;+&nbsp;1. The figure below is
    drawn at ${spell(R.world_size)} devices so it fits a screen; the run used ${int(world)}, and the rule is the
    same. Move the step and watch each chunk's sum complete.`;
  s.append(ringIntro);

  s.append(
    figure(
      ringExplainer(M),
      `<b>Each step, every device sends exactly one chunk, so after N − 1 steps each has sent
       (N − 1) chunks of P/N — the formula P·(N−1)/N, one phase at a time.</b> Drawn at
       ${spell(R.world_size)} devices, a chunk is 1/${R.world_size} of this model's
       ${int(R.payload_bytes)}-byte gradient buffer, so the bytes in the readout are the formula's
       prediction at that size, not a count. At the run's ${int(world)} devices the counters recorded
       ${int(mm['0'].communication.per_step_sent.reduce_scatter)} bytes per phase, equal to the same
       formula. The simulator runs this ring once per unit — ${spell(R.units)} units, which is why data
       parallelism counts ${spell(mm['0'].communication.collectives_per_step)} ring passes a step.`
    )
  );

  const trick = el('p', 'say');
  trick.innerHTML = `<b>That half-way point is the whole trick.</b> Data parallelism's all-reduce
    already <i>is</i> a reduce-scatter followed by an all-gather. ZeRO-1 and ZeRO-2 run the same two
    phases and simply keep what each device holds half way — its complete slice of the summed
    gradient, exactly what it needs to update its slice of the optimiser state. So they cost
    <b>no extra communication</b>. ZeRO-3 frees each unit's weights after the forward pass and must
    gather them a second time for the backward pass, which costs one more phase:
    <b>${M.page.zero3_sent_over_dp}×</b> the bytes.`;
  s.append(trick);

  s.append(el('h3', null, 'What people get wrong about it'));
  const wrong1 = el('p', 'say');
  wrong1.innerHTML = `<b>"A bigger batch means more copies of the model."</b> It does not. The batch
    multiplies <i>activations</i>, not weights: here each device processes
    ${spell(M.config.model.batch_size)} sequence of ${int(M.config.model.seq_len)} tokens a step and
    holds one copy of the weights. Data parallelism has N copies because it has N <i>devices</i>,
    which is a separate fact from how many examples each one reads.`;
  s.append(wrong1);
  const wrong2 = el('p', 'say');
  wrong2.innerHTML = `<b>"ZeRO-3 gives each device some of the layers."</b> That is pipeline
    parallelism, a different technique. ZeRO-3 does the opposite: every device holds <b>a slice of
    every layer</b> — device <i>r</i> keeps slice <i>r</i> of the embeddings, of every block and of
    the head, ${int(embed.shard)} of the embedding table's ${int(embed.numel)} weights — and every
    device still runs every layer on its own data, gathering that layer's full weights for the
    moment it needs them.`;
  s.append(wrong2);
}

/* ============================================================== 5 · method */

function chapterMethod(M) {
  const c = M.config;
  const topo = M.topology;
  const mm = M.modes[M.main_mode];
  const s = section(
    'method',
    'method',
    'The apparatus',
    'A cluster that fits inside one program',
    [
      `The devices are objects inside one Python process on a laptop CPU. That is a choice, not a
       compromise: inside one process every tensor a device holds has a storage whose bytes can be
       added up, and every send is a function call a counter can see. <b>The price is that nothing
       here is a time</b> — no byte crosses a wire.`,
    ],
    { short: 'The apparatus', sub: 'one process playing a cluster' }
  );

  s.append(
    table(
      ['setting', 'value'],
      [
        {
          cells: [
            'devices',
            `${int(topo.world_size)}, on ${int(topo.nodes)} machines of ${int(topo.devices_per_node)},
             joined in one ring`,
          ],
        },
        {
          cells: [
            'model',
            `exercise 09's: ${int(c.model.n_layer)} blocks, width ${int(c.model.d_model)},
             ${int(c.model.n_head)} heads, a ${int(c.model.vocab_size)}-entry vocabulary —
             ${int(M.model.params)} weights in ${spell(M.model.units.length)} units`,
          ],
        },
        {
          cells: [
            'training',
            `${int(c.steps)} AdamW steps at ${c.learning_rate}, ${spell(c.model.batch_size)} sequence
             of ${int(c.model.seq_len)} tokens per device per step`,
          ],
        },
        {
          cells: [
            'what is counted',
            `the storage bytes of every buffer a stage keeps, once per storage, on every device; every
             byte every ring hop sends; the forward and backward arithmetic, by torch's own counter`,
          ],
        },
        {
          cells: [
            'what is not',
            'activations, temporaries inside one optimiser update, and anything a real allocator adds',
          ],
          __mark: 'warn',
        },
        {
          cells: [
            'time',
            `<b>assumed</b>, not measured: ${c.intra_node_bandwidth / 1e9} GB/s inside a machine,
             ${c.inter_node_bandwidth / 1e9} GB/s between machines, ${c.device_flops / 1e12} TFLOP/s per
             device, applied to the counts`,
          ],
          __mark: 'warn',
        },
      ]
    )
  );

  const note = el('p', 'say');
  note.innerHTML = `<b>A view costs its whole storage.</b> The ledger charges each tensor the bytes
    of the memory behind it, so a slice cut from a full buffer without being copied costs the full
    buffer — the honest price, because the full buffer is still alive. Every device's ledger came out
    identical to device 0's under every stage, and so did every device's arithmetic:
    ${int(mm['0'].compute.forward_flops)} forward operations a step whichever stage ran.`;
  s.append(note);
}

