/* ============================================================== 7 · results */

/* -------------------------------------------------------- the per-device budget (Budget)
 *
 * Family: Budget (EXPLAINER_PROMPT §10) — "you cannot have everything": the bill per weight is
 * fixed, and a stage only decides how much of it each device carries. All four stages are drawn at
 * once (§18: show everything); the controls change the precision and which stage's ledger is read
 * out beside its formula, never which bars are visible.
 */
function budgetExplainer(M) {
  const P = M.page;
  const modes = [M.main_mode, ...Object.keys(M.modes).filter((m) => m !== M.main_mode)];
  let mode = M.main_mode;
  let pick = '3';

  const W = 640;
  const x0 = 82;
  const x1 = 470;
  const rowH = 54;
  const top = 34;
  const barH = 26;
  const H = top + rowH * STAGES.length + 20;

  /* stateFor(mode, stage) — PURE. */
  const stateFor = (m, k) => {
    const blocks = M.modes[m];
    const max = Math.max(...STAGES.map((s) => blocks[s].memory.peak_total));
    const scale = (b) => (b / max) * (x1 - x0);
    const rows = STAGES.map((s) => {
      let x = x0;
      const segs = CATS.map((c) => {
        const width = scale(blocks[s].memory.measured[c]);
        const seg = { c, x, width };
        x += width;
        return seg;
      });
      return {
        s,
        segs,
        end: x,
        ghost: scale(P.transient_extra[m][s]),
        tick: x0 + scale(blocks[s].memory.predicted.total),
        total: blocks[s].memory.measured.total,
        perWeight: P.per_weight[m][s].total,
      };
    });
    return { m, k, rows, picked: blocks[k], equal: P.memory_equal[m][k] };
  };

  const guard = (m, k) => (!M.modes[m] || !M.modes[m][k] ? { note: 'No such run.' } : null);

  const wrap = el('div', 'budget');
  const ctl = el('div', 'budget-ctl');
  const precision = tabs('Precision', modes.map((m) => [m, m]), (m) => show(m, pick));
  const stagePick = tabs('Stage to read out', STAGES.map((k) => [k, tag(k)]), (k) => show(mode, k));
  ctl.append(precision, stagePick);

  const chart = svg('svg', {
    viewBox: `0 0 ${W} ${H}`,
    class: 'figsvg budgetfig',
    role: 'img',
    'aria-label':
      'Bytes one device keeps under each stage, as a bar split into weights, gradients and ' +
      'optimiser state, with the formula marked at each bar end and the short-lived peak drawn dashed.',
  });
  chart.append(svgText(x0, 18, 'lab', 'bytes kept by one device'));
  chart.append(svgText(W - 4, 18, 'lab end', '| = the formula'));

  const rowEls = STAGES.map((s, r) => {
    const y = top + r * rowH;
    const g = svg('g', { class: 'brow' });
    const name = svgText(0, y + barH / 2 + 5, 'lab strong', tag(s));
    const segs = CATS.map((c) => {
      const rect = svg('rect', { x: x0, y, width: 0, height: barH, class: `seg ${catSeries(M, c)}` });
      const t = svgText(x0, y + barH / 2 + 4, 'seg-t mid', CAT_SHORT[c]);
      g.append(rect, t);
      return { rect, t };
    });
    const ghost = svg('rect', { x: x0, y: y + 1, width: 0, height: barH - 2, rx: 3, class: 'ghost' });
    const tick = svg('line', { x1: x0, x2: x0, y1: y - 5, y2: y + barH + 5, class: 'ftick' });
    const val = svgText(x0, y + barH / 2 + 5, 'val', '');
    const sub = svgText(x0, y + barH + 16, 'lab faint', '');
    g.prepend(name);
    g.append(ghost, tick, val, sub);
    chart.append(g);
    return { g, segs, ghost, tick, val, sub };
  });

  const read = el('div', 'budget-read');
  let drawn = null;

  /* show(mode, stage) — RENDER ONLY. */
  const show = (m, k) => {
    const refused = guard(m, k);
    if (refused) {
      read.textContent = refused.note;
      return;
    }
    mode = m;
    pick = k;
    precision.mark(m);
    stagePick.mark(k);
    const st = stateFor(m, k);
    const from = drawn;
    drawn = st;
    morph((f) => {
      st.rows.forEach((row, r) => {
        const e = rowEls[r];
        const prev = from ? from.rows[r] : row;
        row.segs.forEach((seg, i) => {
          const px = prev.segs[i].x + (seg.x - prev.segs[i].x) * f;
          const pw = prev.segs[i].width + (seg.width - prev.segs[i].width) * f;
          e.segs[i].rect.setAttribute('x', px.toFixed(2));
          e.segs[i].rect.setAttribute('width', Math.max(0, pw).toFixed(2));
          e.segs[i].t.setAttribute('x', (px + pw / 2).toFixed(2));
          e.segs[i].t.style.opacity = pw > 18 ? '1' : '0';
        });
        const end = prev.end + (row.end - prev.end) * f;
        const ghost = prev.ghost + (row.ghost - prev.ghost) * f;
        e.ghost.setAttribute('x', end.toFixed(2));
        e.ghost.setAttribute('width', Math.max(0, ghost).toFixed(2));
        const tick = prev.tick + (row.tick - prev.tick) * f;
        e.tick.setAttribute('x1', tick.toFixed(2));
        e.tick.setAttribute('x2', tick.toFixed(2));
        e.val.setAttribute('x', (end + ghost + 10).toFixed(2));
      });
    });
    st.rows.forEach((row, r) => {
      const e = rowEls[r];
      e.val.textContent = `${int(row.total)} B`;
      e.sub.textContent = `${bpw(row.perWeight)} bytes per weight`;
      e.g.setAttribute('class', `brow${row.s === k ? ' on' : ''}`);
    });

    const blk = st.picked.memory;
    const rows = CATS.map((c) => ({
      cells: [
        CAT_LABEL[c],
        int(blk.measured[c]),
        int(blk.predicted[c]),
        st.equal[c] ? 'equal' : '<b>differs</b>',
      ],
      __mark: st.equal[c] ? undefined : 'bad',
    }));
    rows.push({
      cells: [
        '<b>total</b>',
        `<b>${int(blk.measured.total)}</b>`,
        `<b>${int(blk.predicted.total)}</b>`,
        st.equal.total ? '<b>equal</b>' : '<b>differs</b>',
      ],
      __mark: st.equal.total ? 'good' : 'bad',
    });
    const extra = P.transient_extra[m][k];
    read.replaceChildren(
      table([tag(k), 'ledger', 'formula', ''], rows, 'mini'),
      Object.assign(el('p', 'say small'), {
        innerHTML: extra
          ? `For a moment each step this device also holds <b>${int(extra)}</b> more bytes — one unit's
             full ${k === '3' ? 'weights or gradient' : 'gradient'}, the dashed extension above — so
             its peak is ${int(blk.peak_total)}.`
          : 'This stage holds nothing beyond its persistent state, so its peak is its total.',
      })
    );
  };

  wrap.playAll = () => show(M.main_mode, '3');
  PLAYABLE.push(wrap);
  wrap.append(ctl, scroller(chart), read);
  show(mode, pick);
  return wrap;
}

function scalingFigure(M) {
  const rows = M.scaling.rows;
  const sizes = M.scaling.world_sizes;
  const F = M.page.formula[M.main_mode];
  const W = 640;
  const H = 300;
  const pad = { l: 46, r: 92, t: 30, b: 40 };
  const maxN = Math.max(...sizes);
  const top = Math.max(...rows.map((r) => r.measured));
  const x = (n) => pad.l + (Math.log2(n) / Math.log2(maxN)) * (W - pad.l - pad.r);
  const y = (v) => pad.t + (1 - v / top) * (H - pad.t - pad.b);

  const node = svg('svg', {
    viewBox: `0 0 ${W} ${H}`,
    class: 'figsvg linefig',
    role: 'img',
    'aria-label':
      'Measured bytes per weight on one device against the number of devices, one line per ' +
      'stage: data parallelism stays flat, ZeRO-1 and ZeRO-2 fall towards their floors, ZeRO-3 ' +
      'keeps falling.',
  });
  for (const v of [0, top / 4, top / 2, (3 * top) / 4, top]) {
    node.append(
      svg('line', { x1: pad.l, x2: W - pad.r, y1: y(v), y2: y(v), class: 'gridline' }),
      svgText(pad.l - 8, y(v) + 4, 'lab end', bpw(v))
    );
  }
  node.append(svgText(4, pad.t - 8, 'lab', 'bytes per weight'));
  for (const n of sizes) node.append(svgText(x(n), H - pad.b + 18, 'lab mid', String(n)));
  node.append(svgText((pad.l + W - pad.r) / 2, H - 6, 'lab mid', 'devices, N'));

  // Floors, dotted, for the two stages that have one above zero and below data parallelism.
  for (const k of ['1', '2']) {
    node.append(
      svg('line', { x1: pad.l, x2: W - pad.r, y1: y(F[k].floor), y2: y(F[k].floor), class: `floor s${k}` }),
      svgText(W - pad.r + 6, y(F[k].floor) + 14, `lab s${k}-t`, `${tag(k)} floor`)
    );
  }

  const marks = { 0: 'circle', 1: 'square', 2: 'diamond', 3: 'triangle' };
  for (const k of STAGES) {
    const pts = sizes.map((n) => rows.find((r) => r.stage === Number(k) && r.world_size === n));
    node.append(
      svg('path', {
        d: pts.map((r, i) => `${i ? 'L' : 'M'} ${x(r.world_size).toFixed(1)} ${y(r.measured).toFixed(1)}`).join(' '),
        class: `series s${k}`,
      })
    );
    for (const r of pts) node.append(marker(marks[k], x(r.world_size), y(r.measured), `mk s${k}`));
    const end = pts[pts.length - 1];
    node.append(svgText(W - pad.r + 6, y(end.measured) + 4, `lab strong s${k}-t`, tag(k)));
  }

  // N = 3: the one size with padding. A ring around each of its points, and a label.
  const padded = rows.filter((r) => r.measured !== r.measured_real);
  if (padded.length) {
    const n = padded[0].world_size;
    node.append(
      svg('line', { x1: x(n), x2: x(n), y1: pad.t, y2: H - pad.b, class: 'padline' }),
      svgText(x(n) + 6, pad.t + 34, 'lab', `N = ${n}: padding`)
    );
  }
  return node;
}

/** A small marker of a given shape — form, so a stage reads without its colour. */
function marker(shape, cx, cy, cls) {
  const r = 4.5;
  if (shape === 'circle') return svg('circle', { cx, cy, r, class: cls });
  if (shape === 'square') return svg('rect', { x: cx - r, y: cy - r, width: 2 * r, height: 2 * r, class: cls });
  if (shape === 'diamond') {
    return svg('path', { d: `M ${cx} ${cy - r - 1} L ${cx + r + 1} ${cy} L ${cx} ${cy + r + 1} L ${cx - r - 1} ${cy} Z`, class: cls });
  }
  return svg('path', { d: `M ${cx} ${cy - r - 1} L ${cx + r + 1} ${cy + r} L ${cx - r - 1} ${cy + r} Z`, class: cls });
}

/* -------------------------------------------------------- the 30B ladder (Optimizer)
 *
 * Family: Optimizer (EXPLAINER_PROMPT §10) — "there is an optimum": drag N until a stage's curve
 * crosses the card. One predict-before-reveal moment. Every mark is DASHED or HATCHED, because
 * nothing here ran: it is `formulas.ladder`, the function whose smaller sizes the ledger matched.
 */
function ladderExplainer(M) {
  const L = M.page.slider;
  const card = M.ladder.card_gib;
  const sizes = L.world_sizes;
  const target = '2';
  const answer = L.first_fit[target];

  const W = 640;
  const H = 400;
  const pad = { l: 52, r: 70, t: 34, b: 40 };
  const all = STAGES.flatMap((k) => L.gib[k]);
  const lo = Math.min(...all);
  const hi = Math.max(...all);
  const lgLo = Math.floor(Math.log10(lo));
  const lgHi = Math.ceil(Math.log10(hi));
  const x = (n) => pad.l + ((n - sizes[0]) / (sizes[sizes.length - 1] - sizes[0])) * (W - pad.l - pad.r);
  const y = (g) => pad.t + (1 - (Math.log10(g) - lgLo) / (lgHi - lgLo)) * (H - pad.t - pad.b);

  /* stateFor(n) — PURE. */
  const stateFor = (n) => {
    const i = sizes.indexOf(n);
    return {
      n,
      rows: STAGES.map((k) => ({
        k,
        gib: L.gib[k][i],
        fits: L.fits[k][i],
        full: L.fits[k][i] && (L.first_headroom[k] === null || n < L.first_headroom[k]),
      })),
    };
  };
  const guard = (n) => (!sizes.includes(n) ? { note: 'The ladder covers whole numbers of devices only.' } : null);

  const wrap = el('div', 'ladder');

  // The prediction, before anything is revealed.
  const ask = el('div', 'predict');
  const askLab = el('label', null, `Guess first: on how few devices does ${tag(target)} fit a
    ${M.ladder.params / 1e9}-billion-weight model?`);
  const guessIn = el('input');
  guessIn.type = 'number';
  guessIn.min = String(sizes[0]);
  guessIn.max = String(sizes[sizes.length - 1]);
  guessIn.id = 'ladder-guess';
  askLab.htmlFor = 'ladder-guess';
  const reveal = el('button', 'btn', 'Reveal');
  reveal.type = 'button';
  ask.append(askLab, guessIn, reveal);
  const verdict = el('div', 'predict-v');
  verdict.setAttribute('aria-live', 'polite');

  const chart = svg('svg', {
    viewBox: `0 0 ${W} ${H}`,
    class: 'figsvg linefig ladderfig',
    role: 'img',
    'aria-label':
      `Predicted gibibytes per device for a ${M.ladder.params / 1e9}-billion-weight model against ` +
      'the number of devices, one dashed curve per stage, with the card’s capacity as a line.',
  });
  // Everything above the card does not fit: the page's one red region.
  chart.append(svg('rect', { x: pad.l, y: pad.t, width: W - pad.l - pad.r, height: y(card) - pad.t, class: 'nofit' }));
  for (let e = lgLo; e <= lgHi; e += 1) {
    const g = 10 ** e;
    chart.append(
      svg('line', { x1: pad.l, x2: W - pad.r, y1: y(g), y2: y(g), class: 'gridline' }),
      svgText(pad.l - 8, y(g) + 4, 'lab end', String(g))
    );
  }
  chart.append(svgText(4, pad.t - 14, 'lab', 'GiB per device'));
  chart.append(
    svg('line', { x1: pad.l, x2: W - pad.r, y1: y(card), y2: y(card), class: 'cardline' }),
    svgText(x(sizes[Math.floor(sizes.length / 2)]), y(card) - 6, 'lab strong mid', `the card: ${gib(card)} GiB`)
  );
  for (const n of M.config.ladder_world_sizes.concat(sizes[0])) {
    chart.append(svgText(x(n), H - pad.b + 18, 'lab mid', String(n)));
  }
  chart.append(svgText((pad.l + W - pad.r) / 2, H - 6, 'lab mid', 'devices, N'));
  for (const k of ['1', '2']) {
    const f = L.floor_gib[k];
    chart.append(
      svg('line', { x1: pad.l, x2: W - pad.r, y1: y(f), y2: y(f), class: `floor s${k}` }),
      svgText(W - pad.r - 4, y(f) + 13, `lab end s${k}-t`, `${tag(k)} floor ${gib(f)}`)
    );
  }
  for (const k of STAGES) {
    chart.append(
      svg('path', {
        d: sizes.map((n, i) => `${i ? 'L' : 'M'} ${x(n).toFixed(1)} ${y(L.gib[k][i]).toFixed(1)}`).join(' '),
        class: `series predicted s${k}`,
      }),
      svgText(W - pad.r + 6, y(L.gib[k][sizes.length - 1]) + 4, `lab strong s${k}-t`, tag(k))
    );
  }
  const cursor = svg('line', { x1: 0, x2: 0, y1: pad.t, y2: H - pad.b, class: 'cursor' });
  const dots = STAGES.map((k) => svg('circle', { cx: 0, cy: 0, r: 5, class: `hollow s${k}` }));
  const marks = svg('g', { class: 'guessmarks' });
  chart.append(cursor, ...dots, marks);

  const ctl = el('div', 'ring-ctl');
  const lab = el('label', null, 'Devices');
  const range = el('input');
  range.type = 'range';
  range.min = String(sizes[0]);
  range.max = String(sizes[sizes.length - 1]);
  range.step = '1';
  range.value = String(M.topology.world_size);
  range.id = 'ladder-n';
  lab.htmlFor = 'ladder-n';
  const out = el('output', 'ring-out');
  out.htmlFor = 'ladder-n';
  ctl.append(lab, range, out);
  const read = el('div', 'ladder-read');

  /* show(n) — RENDER ONLY. */
  const show = (n) => {
    const refused = guard(n);
    if (refused) {
      read.textContent = refused.note;
      return;
    }
    range.value = String(n);
    out.textContent = `N = ${n}`;
    const st = stateFor(n);
    cursor.setAttribute('x1', x(n));
    cursor.setAttribute('x2', x(n));
    st.rows.forEach((row, i) => {
      dots[i].setAttribute('cx', x(n));
      dots[i].setAttribute('cy', y(row.gib));
    });
    read.replaceChildren(
      ...st.rows.map((row) => {
        const line = el('div', `lrow ${row.fits ? 'fit' : 'nofit'}`);
        line.innerHTML = `<span class="lk s${row.k}-t">${tag(row.k)}</span>
          <span class="lv">${gib(row.gib)} GiB</span>
          <span class="lf">${row.fits ? (row.full ? 'fits — to the byte, nothing left for activations' : 'fits') : 'does not fit'}</span>`;
        return line;
      })
    );
  };

  const doReveal = (withGuess) => {
    const g = Number(guessIn.value);
    const has = withGuess && sizes.includes(g);
    marks.replaceChildren(
      svg('line', { x1: x(answer), x2: x(answer), y1: pad.t, y2: H - pad.b, class: 'answer' }),
      svgText(x(answer) + 5, H - pad.b - 8, 'lab strong', `${tag(target)} fits from N = ${answer}`)
    );
    if (has) {
      marks.append(
        svg('line', { x1: x(g), x2: x(g), y1: pad.t, y2: H - pad.b, class: 'guess' }),
        svgText(x(g) + 5, pad.t + 26, 'lab', `your guess ${g}`)
      );
    }
    const gap = has ? g - answer : null;
    verdict.innerHTML = `${has ? `You guessed <b>${g}</b>; ` : ''}the formula says
      <b>${answer}</b>${gap === null || gap === 0 ? '.' : `, so you were ${Math.abs(gap)} ${gap < 0 ? 'low' : 'high'}.`}
      At ${answer} devices ${tag(target)} needs <b>exactly</b> the card — not a byte to spare for
      activations — so the first size with any room at all is ${L.first_headroom[target]}.`;
    show(answer);
  };
  reveal.addEventListener('click', () => doReveal(true));
  range.addEventListener('input', () => show(Number(range.value)));

  wrap.playAll = () => doReveal(false);
  PLAYABLE.push(wrap);
  wrap.append(ask, verdict, ctl, scroller(chart), read);
  show(M.topology.world_size);
  return wrap;
}

/* -------------------------------------------------------- try to break bit-identity (Adversary)
 *
 * Family: Adversary (EXPLAINER_PROMPT §10) — "this boundary is real": the reader tries every ZeRO
 * run against data parallelism, hunting for one weight that differs, and fails. The last button is
 * the self-refutation: change how the sum is ordered and the boundary moves.
 */
function adversaryExplainer(M) {
  const eq = M.equivalence;
  const modes = Object.keys(M.modes);
  const keys = STAGES.filter((k) => k !== '0');
  const tried = new Set();

  /* stateFor — PURE. */
  const stateFor = () => ({
    tried: tried.size,
    total: modes.length * keys.length,
    found: [...tried].filter((id) => id !== 'ref').filter((id) => {
      const [m, k] = id.split('|');
      return !M.page.identical_to_dp[m][k];
    }).length,
    ref: tried.has('ref'),
  });
  const guard = () => null;

  const wrap = el('div', 'adv');
  const grid = el('div', 'adv-grid');
  grid.setAttribute('role', 'group');
  grid.setAttribute('aria-label', 'Runs to compare with data parallelism');
  const buttons = [];
  for (const m of modes) {
    const row = el('div', 'adv-row');
    row.append(el('div', 'adv-mode', m));
    for (const k of keys) {
      const b = el('button', 'adv-cell', `${tag(k)}`);
      b.type = 'button';
      b.dataset.id = `${m}|${k}`;
      b.addEventListener('click', () => {
        tried.add(b.dataset.id);
        show();
      });
      row.append(b);
      buttons.push(b);
    }
    grid.append(row);
  }
  const refRow = el('div', 'adv-row');
  refRow.append(el('div', 'adv-mode', 'different order'));
  const refBtn = el('button', 'adv-cell ref', 'one device, fp32');
  refBtn.type = 'button';
  refBtn.dataset.id = 'ref';
  refBtn.addEventListener('click', () => {
    tried.add('ref');
    show();
  });
  refRow.append(refBtn);
  grid.append(refRow);
  const read = el('div', 'adv-read');
  read.setAttribute('aria-live', 'polite');

  /* show() — RENDER ONLY. */
  const show = () => {
    if (guard()) return;
    const st = stateFor();
    for (const b of buttons) {
      if (!tried.has(b.dataset.id)) continue;
      const [m, k] = b.dataset.id.split('|');
      const d = M.modes[m][k].max_abs_vs_dp;
      b.innerHTML = `${tag(k)} <span class="adv-v">${sci(d)}</span>`;
      b.classList.add(M.page.identical_to_dp[m][k] ? 'same' : 'diff');
    }
    if (st.ref) {
      refBtn.innerHTML = `one device, fp32 <span class="adv-v">${sci(eq.fp32_weights_max_abs_except_key_bias)}</span>`;
      refBtn.classList.add('diff');
    }
    read.innerHTML = `Tried <b>${st.tried - (st.ref ? 1 : 0)}</b> of ${st.total} ZeRO runs;
      weights found differing from data parallelism: <b>${st.found}</b>.${
        st.ref
          ? ` The last button is not a ZeRO run: it is one device training the whole batch with
             PyTorch’s own optimiser, and its weights differ by up to
             ${sci(eq.fp32_weights_max_abs_except_key_bias)}, and by up to
             ${sci(eq.fp32_weights_max_abs_key_bias)} on the attention key bias. Same arithmetic,
             different order of addition.`
          : ''
      }`;
  };

  wrap.playAll = () => {
    for (const b of buttons) tried.add(b.dataset.id);
    tried.add('ref');
    show();
  };
  PLAYABLE.push(wrap);
  wrap.append(grid, read);
  show();
  return wrap;
}

function chapterResults(M) {
  const mm = M.modes[M.main_mode];
  const P = M.page;
  const c = M.config;
  const world = M.topology.world_size;
  const L = P.slider;
  const s = section(
    'results',
    'results',
    'The ledger',
    'Every ledger equals its formula',
    [
      `Every figure below is read from <code>results/zero.json</code>, which the simulator wrote with
       its provenance attached. Nothing on this page is typed, and a test regenerates the page's data
       and fails if the tracked copy differs.`,
    ],
    { short: 'The counts', sub: 'memory, traffic, and the ladder' }
  );

  s.append(el('h3', null, 'Memory, on one device'));
  const memIntro = el('p', 'say');
  memIntro.innerHTML = `At ${int(world)} devices data parallelism keeps
    ${int(mm['0'].memory.measured.total)} bytes on each one and ZeRO-3 keeps
    ${int(mm['3'].memory.measured.total)} — <b>${P.dp_bytes_over_zero3} times less</b>. Pick a stage
    to set its ledger beside its formula, and switch precision to see the same arithmetic with no
    master copy.`;
  s.append(memIntro);
  s.append(
    figure(
      budgetExplainer(M),
      `<b>Each bar is one device's ledger, and the tick at its end is the hand formula — they land on
       the same pixel in every stage and both precisions, because the ledger and the formula agree to
       the byte.</b> The dashed extension is what sharding costs back: for a moment each step, ZeRO-2
       holds one unit's full gradient and ZeRO-3 one unit's full weights, at most
       ${int(mm['3'].memory.largest_unit_bytes.params)} bytes. A ledger that ever exceeded one unit
       there would mean a gathered buffer was never freed.`
    )
  );

  s.append(el('h3', null, 'Memory as the cluster grows'));
  const pad = M.scaling.rows.filter((r) => r.measured !== r.measured_real);
  const scaleIntro = el('p', 'say');
  scaleIntro.innerHTML = `A fresh cluster at each size, one step each, ledger read afterwards. Data
    parallelism is flat at every size; ZeRO-1 and ZeRO-2 fall towards their floors; only ZeRO-3
    keeps falling.`;
  s.append(scaleIntro);
  s.append(
    figure(
      scalingFigure(M),
      `<b>Every point is a measurement, and ${M.page.scaling_all_match ? 'every one equals' : 'not every one equals'}
       the formula — at ${spell(M.scaling.world_sizes.length)} sizes, for all
       ${spell(STAGES.length)} stages.</b> The
       dotted lines are the floors the formulas promise and the curves are visibly bending towards
       them. ${pad.length ? `N&nbsp;=&nbsp;${pad[0].world_size} is there on purpose: it is the one size
       where the units do not divide evenly, so zeros are added and real weights cost slightly more —
       ZeRO-3 ${bpw(pad.find((r) => r.stage === 3).measured_real)} bytes per real weight against
       ${bpw(pad.find((r) => r.stage === 3).measured)} per padded one.` : ''}`
    )
  );

  s.append(el('h3', null, 'Communication, per device per step'));
  const commRows = STAGES.map((k) => {
    const cm = mm[k].communication;
    return {
      cells: [
        tag(k),
        int(cm.per_step_sent.reduce_scatter),
        int(cm.per_step_sent.all_gather),
        `<b>${int(cm.per_step_sent.total)}</b>`,
        int(cm.predicted.total),
        `${P.comm_multiple[M.main_mode][k]} × P·(N−1)/N`,
        String(cm.collectives_per_step),
      ],
      __mark: k === '3' ? 'warn' : undefined,
    };
  });
  s.append(
    table(
      ['stage', 'reduce-scatter', 'all-gather', 'sent, counted', 'formula', 'in units of one phase', 'ring passes'],
      commRows
    )
  );
  const time = el('p', 'say');
  time.innerHTML = `<b>In seconds — on assumed hardware, not measured.</b> At an assumed
    ${c.intra_node_bandwidth / 1e9} GB/s inside a machine and ${c.inter_node_bandwidth / 1e9} GB/s
    between machines, with a ring paced by its slowest link and no overlap of computing and sending,
    one step's communication would take ${usec(mm['0'].time_model.comm_seconds)} µs for data
    parallelism, ZeRO-1 and ZeRO-2 alike, and ${usec(mm['3'].time_model.comm_seconds)} µs for ZeRO-3.
    Change the assumptions and every time changes; the byte counts above do not.`;
  s.append(time);

  s.append(el('h3', null, `The same arithmetic, at ${M.ladder.params / 1e9} billion weights`));
  const ladderIntro = el('p', 'say');
  ladderIntro.innerHTML = `Nothing is simulated at this size: these are the formulas the ledger just
    matched, multiplied out for a ${M.ladder.params / 1e9}-billion-weight model against an assumed
    ${M.ladder.card_bytes / 1e9} GB card. Make a guess before you move anything.`;
  s.append(ladderIntro);
  s.append(
    figure(
      ladderExplainer(M),
      `<b>A stage fits where its dashed curve crosses below the card, and
       ${spell(STAGES.filter((k) => L.never_fits[k]).length)} of the ${spell(STAGES.length)} never
       cross.</b> Data parallelism is flat at
       ${gib(L.gib['0'][0])} GiB; ZeRO-1 flattens onto its ${gib(L.floor_gib['1'])} GiB floor, above the
       card at any N. ZeRO-2 crosses at ${L.first_fit['2']} devices and ZeRO-3 at ${L.first_fit['3']}.
       Every mark is dashed because it is a prediction, and activations are excluded, so "fits" here is
       necessary, not sufficient.`
    )
  );
  const ladderTail = el('p', 'say');
  ladderTail.innerHTML = `So at this size the real choice is <b>ZeRO-2 on many devices or ZeRO-3 on
    fewer</b>: ZeRO-3 fits from ${L.first_fit['3']} devices where ZeRO-2 needs ${L.first_fit['2']}, and
    pays ${P.zero3_sent_over_dp} times the communication for it. Both first sizes fill the card
    exactly, so in practice each needs at least one device more.`;
  s.append(ladderTail);

  s.append(el('h3', null, 'Does the stage change the answer?'));
  const advIntro = el('p', 'say');
  advIntro.innerHTML = `If ZeRO only changes where numbers live, the trained weights must not change
    at all. Try to find a ZeRO run whose weights differ from data parallelism's after the
    ${spell(c.steps)} training steps.`;
  s.append(advIntro);
  s.append(
    figure(
      adversaryExplainer(M),
      `<b>Every ZeRO run, in both precisions, ends on data parallelism's weights to the last bit:
       the largest difference is ${P.max_abs_vs_dp}.</b> That is a property of this simulator, not of
       ZeRO: here data parallelism's all-reduce is the same ring reduce-scatter ZeRO uses, so the same
       numbers are added in the same order. The last button refutes the stronger claim — sum in a
       different order and agreement is only to rounding.`
    )
  );
}

/* ============================================================== 8 · negatives */

function chapterNegatives(M) {
  const rows = negativeRows(M);
  const s = section(
    'negatives',
    'negatives',
    'What it does not buy',
    'Where the obvious reading is wrong, and what broke on the way',
    [
      `ZeRO is easy to oversell, and so is a simulator that agrees with itself. These are the places
       the obvious reading fails: what ZeRO does not buy, where this run's own numbers stop agreeing,
       and the defects found while building it. <b>The defects were invisible to every test that
       existed at the time</b>; each was found by asking what a number was actually measuring.`,
    ],
    { short: 'The negatives', sub: 'what it does not buy, what broke' }
  );
  s.append(table(['the obvious reading', 'what the run says'], rows, 'grid prose'));
}

/** The negative findings, as data, so a section could count them. */
function negativeRows(M) {
  const mm = M.modes[M.main_mode];
  const eq = M.equivalence;
  const P = M.page;
  return [
    {
      cells: [
        'ZeRO-1 and ZeRO-2 must send less, since they keep less',
        `They send <b>exactly the same</b>: ${int(mm['1'].communication.per_step_sent.total)} bytes a
         step, the same as data parallelism. The saving is memory alone — and that is the good news,
         because it is free.`,
      ],
    },
    {
      cells: [
        'ZeRO-3 removes the memory problem',
        `At the price of ${P.zero3_sent_over_dp} times the communication, and a unit's full weights
         gathered twice a step: its peak is ${int(mm['3'].memory.peak_total)} bytes against a steady
         ${int(mm['3'].memory.measured.total)}. And activations, often the larger bill, are not split
         by any stage.`,
      ],
      __mark: 'warn',
    },
    {
      cells: [
        'A cluster and one device doing the same arithmetic agree everywhere',
        `Everywhere but ${int(eq.key_bias_elements)} weights: ${sci(eq.fp32_weights_max_abs_except_key_bias)}
         at most elsewhere, ${sci(eq.fp32_weights_max_abs_key_bias)} on the attention key bias. The key bias
         adds the same number to every score in a row, and softmax ignores that, so its true gradient
         is exactly zero; what is computed is rounding noise (${sci(eq.key_bias_grad_step1_max_abs)}).
         AdamW divides each gradient by its own running size, which turns noise into a full step —
         and a different order of addition is different noise.`,
      ],
      __mark: 'warn',
    },
    {
      cells: [
        'bf16 training reproduces fp32',
        `Closely, not exactly: the two runs' total weight updates point the same way to a cosine of
         ${eq.mixed_update_cosine.toFixed(6)}, and the losses differ by ${sci(eq.mixed_loss_max_rel)}
         relative. Close is not identical, and the page does not call it identical.`,
      ],
    },
    {
      cells: [
        'An update that reads one element to write one element cannot depend on how a buffer is cut',
        `It did. Built on PyTorch's fused kernels, the optimiser left ZeRO-1 slightly off data
         parallelism: probed on this CPU, the result is
         consistent with a vectorised loop and its scalar tail rounding differently, and a shard
         boundary moving elements between them. Rewritten from operations that each round once, the
         stages agree exactly, and a test cuts buffers at deliberately awkward places.`,
      ],
      __mark: 'bad',
    },
    {
      cells: [
        'The ledger counts what a device holds',
        `It first counted what a tensor <i>looked</i> like: a slice of a full buffer was charged as a
         slice, so dropping one copy left the whole buffer alive while the ledger reported a fraction
         of it, with every test green. It now charges the memory behind each tensor, once.`,
      ],
      __mark: 'bad',
    },
  ];
}

/* ============================================================== 9 · conclusion */

function chapterConclusion(M) {
  const P = M.page;
  const s = section(
    'conclusion',
    'conclusion',
    'The verdict',
    'ZeRO moves bytes; it does not remove them',
    [
      `Every stage pays the same ${spell(P.per_weight[M.main_mode]['0'].total)} bytes per weight in
       total, and computes the same thing. What a stage decides is how much of that bill each device
       carries — and, through the floor, whether adding devices helps at all.`,
      `ZeRO-1 and ZeRO-2 are close to free: the communication is identical to data parallelism's,
       because they keep a half-way result data parallelism throws away. ZeRO-3 is the only stage
       without a floor, and the only one that costs more traffic.`,
    ],
    { short: 'The verdict', sub: 'where the bytes live' }
  );

  const box = el('div', 'takeaway');
  box.innerHTML = `<b>The check to carry away.</b> Before adding devices to fix a memory problem, add
    up what each device keeps <i>whole</i>. If that alone is more than the card, no number of devices
    will help — that is ZeRO-1's ${gib(P.slider.floor_gib['1'])} GiB at
    ${M.ladder.params / 1e9} billion weights — and
    only a stage that splits more of the bill will.`;
  s.append(box);
}

/* ============================================================== 10 · limits */

function chapterLimits(M) {
  const c = M.config;
  const items = [
    `<b>Everything ran in one process on a CPU.</b> The devices are Python objects and nothing crosses a
     network, so no measured number on this page is a time.`,
    `<b>The times are assumed.</b> ${c.intra_node_bandwidth / 1e9} and ${c.inter_node_bandwidth / 1e9}
     GB/s links and ${c.device_flops / 1e12} TFLOP/s devices are inputs, not findings, with a flat ring
     and no overlap. Real libraries use hierarchical collectives and overlap heavily, so only ratios carry
     meaning.`,
    `<b>Activations are excluded</b> from every memory figure, and so are the temporaries inside one
     optimiser update, the ring's chunks in flight, and everything an allocator adds.`,
    `<b>The model is tiny</b> — ${int(M.model.params)} weights — so the cluster finishes in seconds. The
     ladder applies the same formulas at ${M.ladder.params / 1e9} billion weights; it is arithmetic,
     not a run.`,
    `<b>Bit-identity is this simulator's.</b> Its all-reduce is a ring reduce-scatter and all-gather; a
     library that all-reduces another way sums in another order and agrees only to rounding.`,
    `<b>${Spell(c.steps)} steps prove equivalence, not learning.</b> The loss barely moves in that time.
     Prefetching, the latency of gathering unit by unit, and combining ZeRO with other kinds of
     parallelism are not measured.`,
  ];
  const s = section(
    'limits',
    'limits',
    'In the open',
    'What this page cannot establish',
    [
      `In the open text rather than behind a disclosure, because a limitation a reader has to expand
       is a limitation the page is hiding.`,
    ],
    { short: 'The limits', sub: 'what a simulation cannot settle' }
  );
  s.classList.add('notice');
  const ul = el('ul', 'limitlist');
  for (const item of items) {
    const li = el('li');
    li.innerHTML = item;
    ul.append(li);
  }
  s.append(ul);
}

